  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Spirituals and the Roots of American Music$j$, $j${"readings": [{"title": "Exodus 3 (King James Version)", "url": "/portal/bible/Exodus/3"}], "body": "Spirituals are among the most important songs in American history. They were created in the 1700s and 1800s by enslaved African Americans, who combined musical traditions from West Africa with the stories and promises of the Bible. Their authors are mostly unknown, and the songs were passed down by memory and sung in fields, in praise houses and in worship.\n\nSpirituals often use call and response, in which a leader sings a line and the group answers. They use strong rhythm, syncopation, repeated phrases and rich harmony in the voices. Their texts draw on the Bible, especially the stories of Israel's deliverance from Egypt, Daniel in the lions' den, the walls of Jericho and the hope of heaven. Singers saw their own longing for freedom reflected in Exodus 3:7, where God says, I have surely seen the affliction of my people which are in Egypt, and have heard their cry. Some historians believe a few songs carried messages of escape, but scholars disagree about how widely this was true, so we should speak carefully and avoid claiming more than the evidence shows.\n\nSpirituals show faith in hard times. Like Psalm 137, they remember sorrow, yet they also hold hope. They also show the creativity and dignity of people who were treated unjustly.\n\nIn 1871, a group of students at Fisk University in Nashville, Tennessee, formed the Fisk Jubilee Singers. They toured in the United States and Europe to raise money for the school and introduced spirituals to the wider world. Composers such as Harry T. Burleigh arranged spirituals for concert singers, and later composers drew on them. Spirituals are a root of gospel, blues and jazz.\n\nYour task: (1) Define spirituals and tell who created them. (2) Describe call and response and two other features. (3) Explain the importance of the Fisk Jubilee Singers.\n\nFlorida standards: MU.912.H.1, MU.912.H.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.H.2", "script": "Welcome to Unit 4. Listen, now we come home to America, and the story starts with faith in the hardest of times.\n\nSpirituals were created in the 1700s and 1800s by enslaved African Americans. They joined musical traditions from West Africa with the stories and promises of the Bible. The authors are mostly unknown, and the songs were passed down by memory.\n\nNow watch this. Spirituals often use call and response. A leader sings a line and the group answers. They use strong rhythm, repeated phrases and rich harmony. Their texts draw on the Bible, especially Israel's deliverance from Egypt, Daniel in the lions' den and the walls of Jericho. Singers heard their own longing for freedom in Exodus 3:7. I have surely seen the affliction of my people which are in Egypt, and have heard their cry. Some historians think a few songs carried hidden messages, but scholars disagree about how widely, so let us speak carefully.\n\nLook at the Fisk Jubilee Singers. In 1871, students at Fisk University in Nashville formed a group and toured the United States and Europe to raise money for the school. They introduced spirituals to the wider world. Harry T. Burleigh arranged spirituals for concert singers. Spirituals are a root of gospel, blues and jazz.\n\nYour task is to define spirituals, describe call and response, and explain the Fisk Jubilee Singers. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Spirituals and the Roots of American Music$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Gospel Music$j$, $j${"readings": [{"title": "Psalm 40 (King James Version)", "url": "/portal/bible/Psalms/40"}], "body": "Gospel music grew from spirituals, hymns and the sounds of African American churches. It is joyful, expressive and centered on the good news of Jesus Christ. Its sound often includes a choir, a soloist, piano and Hammond organ, handclaps, call and response, improvisation and strong rhythm.\n\nThomas A. Dorsey, who lived from 1899 to 1993, is called the father of gospel music. He was a blues pianist who turned his gifts to sacred song. In 1932, after the sudden death of his wife and newborn son, he wrote Precious Lord, Take My Hand, a song of comfort in grief that is still sung at funerals and in churches around the world. Mahalia Jackson, who lived from 1911 to 1972, was a singer from New Orleans known as the Queen of Gospel. Her powerful voice carried gospel to concert halls and to the civil rights movement, and she sang in Chicago and across the country. Gospel choirs and quartets filled churches, and recordings and radio spread their sound. Later artists such as Edwin Hawkins, Andrae Crouch and Kirk Franklin blended gospel with newer styles.\n\nGospel emphasizes testimony, which means telling what the Lord has done. Psalm 40:3 says, And he hath put a new song in my mouth, even praise unto our God: many shall see it, and fear, and shall trust in the LORD. Good gospel music lifts the song of the whole congregation, and it also invites listeners to trust the Lord.\n\nSingers should care for their voices and give God the glory. Gifts come from Him. First Peter 4:10 says, As every man hath received the gift, even so minister the same one to another, as good stewards of the manifold grace of God.\n\nYour task: (1) Describe the sound and features of gospel music. (2) Tell who Thomas A. Dorsey and Mahalia Jackson were. (3) Explain what First Peter 4:10 teaches musicians.\n\nFlorida standards: MU.912.H.1, MU.912.H.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.H.2", "script": "Welcome back. Listen, if you have ever felt the Spirit move in a church choir, you know what gospel music is.\n\nGospel grew from spirituals, hymns and the sounds of African American churches. It is joyful, expressive and centered on the good news of Jesus Christ. The sound often includes choir, soloist, piano, Hammond organ, handclaps, call and response and improvisation.\n\nNow watch this. Thomas A. Dorsey, 1899 to 1993, is called the father of gospel music. He was a blues pianist who turned his gifts to sacred song. In 1932, after the sudden death of his wife and newborn son, he wrote Precious Lord, Take My Hand, a song of comfort that is still sung around the world. Mahalia Jackson, 1911 to 1972, from New Orleans, was called the Queen of Gospel. Her powerful voice carried gospel to concert halls and to the civil rights movement.\n\nLook at its message. Gospel emphasizes testimony, telling what the Lord has done. Psalm 40:3. And he hath put a new song in my mouth, even praise unto our God: many shall see it, and fear, and shall trust in the LORD.\n\nEvery gift comes from God. First Peter 4:10 says, As every man hath received the gift, even so minister the same one to another, as good stewards of the manifold grace of God.\n\nYour task is to describe gospel, tell who Dorsey and Jackson were, and explain First Peter 4:10. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Gospel Music$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Blues, Jazz, Folk and Country$j$, $j${"readings": [{"title": "Ecclesiastes 3 (King James Version)", "url": "/portal/bible/Ecclesiastes/3"}], "body": "American music is a blend of many traditions. The blues developed in the Deep South, especially the Mississippi Delta, in the late 1800s and early 1900s, from spirituals, work songs and field hollers. The blues often use a twelve bar form, which is a pattern of three phrases over twelve measures, and blue notes, which are bent pitches that sound expressive. Blues songs often express hardship and longing.\n\nJazz grew out of New Orleans in the early 1900s from blues, ragtime, brass band music and African rhythms. Jazz features improvisation, in which players make up music on the spot, and syncopation, which stresses weak beats. It features swing, a rhythmic feel that rocks. Louis Armstrong, who lived from 1901 to 1971, was a trumpeter and singer from New Orleans whose artistry shaped jazz. Duke Ellington, who lived from 1899 to 1974, was a pianist and bandleader who composed hundreds of works, and he wrote a series of Sacred Concerts late in life.\n\nFolk music is music handed down by ordinary people. Country music grew out of folk songs, hymns and string band music in the rural South, and it often tells stories of family, faith and daily life. A tradition called shape note singing, also known as Sacred Harp singing, uses notes in different shapes to help people learn to sing hymns in four parts without instruments. It is still sung today in many places in the South.\n\nEcclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven. Music can express sorrow, joy, work, play and worship. When we listen to many styles, we can see the gifts God has given to people in different times and places. We can enjoy what is good while still asking whether the words and the message are wholesome.\n\nYour task: (1) Describe where the blues and jazz began and two features of each. (2) Explain improvisation and syncopation. (3) Describe shape note singing.\n\nFlorida standards: MU.912.H.1, MU.912.H.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.H.2", "script": "Welcome back. Listen, America has a lot of music, and much of it comes from the same roots.\n\nThe blues developed in the Deep South, especially the Mississippi Delta, from spirituals, work songs and field hollers. The blues often use a twelve bar form and blue notes, which are bent pitches that sound expressive. The blues express hardship and longing.\n\nNow watch this. Jazz grew out of New Orleans in the early 1900s from blues, ragtime, brass bands and African rhythms. It features improvisation, which means making up music on the spot, and syncopation, which stresses weak beats. Louis Armstrong, 1901 to 1971, was a trumpeter and singer from New Orleans who shaped jazz. Duke Ellington, 1899 to 1974, was a pianist and bandleader who wrote hundreds of works, including Sacred Concerts late in life.\n\nLook at folk and country. Folk music is handed down by ordinary people. Country music grew from folk songs, hymns and string bands in the rural South, and it tells stories of family, faith and daily life. Shape note singing, also called Sacred Harp singing, uses notes in different shapes to help people sing hymns in four parts without instruments.\n\nEcclesiastes 3:1 says, To every thing there is a season. Listen widely, enjoy what is good, and ask whether the words are wholesome.\n\nYour task is to describe the blues and jazz, explain improvisation and syncopation, and describe shape note singing. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Blues, Jazz, Folk and Country$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Popular Music and Wise Listening$j$, $j${"readings": [{"title": "Romans 12 (King James Version)", "url": "/portal/bible/Romans/12"}], "body": "Popular music is music enjoyed by many people and spread through radio, recordings, film, television and the internet. Rock and roll grew in the 1950s from blues, gospel, country and rhythm and blues. Soul, funk, pop and many other styles followed. Hip hop began in the Bronx in New York City in the 1970s, with DJs, rapping, dance and graffiti art, and it has grown into a global culture. Contemporary Christian music grew in the late 1900s as believers brought new styles into worship and witness. Today people can listen to almost anything on a phone in seconds.\n\nBecause so much music is available, listeners need wisdom. Music affects mood and thought, and it can bring peace or stir up anger. Words matter because they teach. Romans 12:2 says, And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God. Philippians 4:8 says, Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.\n\nHere are questions for wise listening. What do the words say, and are they true? What message does the song teach about God, people and life? How do I feel and act after listening to it? Is it helping or hurting my walk with the Lord? Would I be comfortable if my family or pastor heard it? We should not judge a style simply because it is unfamiliar. Good and poor songs exist in every style. Pay attention to the message and the heart, and apply the same test to all.\n\nParents and guardians guide the music young people listen to, and teens should be honest and respectful in these conversations. Also protect your hearing. Very loud sound can damage the ears for life.\n\nYour task: (1) Name three popular styles and where they came from. (2) Write five questions you can ask to evaluate a song. (3) Explain Philippians 4:8 in your own words.\n\nFlorida standards: MU.912.C.1, MU.912.C.3, MU.912.F.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.C.1, MU.912.C.3, MU.912.F.1", "script": "Welcome back. Listen, you carry a library of music in your pocket. Today we talk about how to listen wisely.\n\nPopular music is music enjoyed by many and spread by radio, recordings, film, television and the internet. Rock and roll grew in the 1950s from blues, gospel, country and rhythm and blues. Hip hop began in the Bronx in New York City in the 1970s and has become a global culture. Contemporary Christian music grew in the late 1900s as believers brought new styles into worship and witness.\n\nNow watch this. With so much available, you need wisdom. Music affects mood and thought. Words teach. Romans 12:2 says, be ye transformed by the renewing of your mind. Philippians 4:8 says, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report, think on these things.\n\nLook at five questions. What do the words say, and are they true? What does the song teach about God, people and life? How do I feel and act after listening? Is it helping or hurting my walk with the Lord? Would I be comfortable if my family or pastor heard it? Good and poor songs exist in every style, so apply the same test to all.\n\nRespect your parents and guardians as they guide your listening. And protect your hearing. Very loud sound can damage your ears for life.\n\nYour task is to name three popular styles, write five evaluation questions and explain Philippians 4:8. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Popular Music and Wise Listening$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: American Music Traditions$j$, $j${"prompt": "Write a report of at least 250 words on American music traditions. Use complete sentences and label each part. Psalm 40:3 says, And he hath put a new song in my mouth, even praise unto our God: many shall see it, and fear, and shall trust in the LORD.\n\nPart 1: Describe spirituals, who created them, and three features of their style.\nPart 2: Explain the importance of the Fisk Jubilee Singers, Thomas A. Dorsey and Mahalia Jackson.\nPart 3: Describe the origins and features of the blues and jazz, using improvisation, syncopation and blue notes correctly.\nPart 4: Describe folk, country, shape note singing and two popular styles and where they came from.\nPart 5: Choose one song in any style and evaluate it using the five wise listening questions from lesson 4.4. Explain how Philippians 4:8 guides your choices.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 20 points. Part 4: 15 points. Part 5: 25 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: American Music Traditions$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Faith in Hard Times$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells how music has helped you or someone you know during a hard time, (2) explains what spirituals teach about faith and hope in suffering, (3) describes how you can listen to different styles of music with respect while still testing the message, and (4) connects your answer to Philippians 4:8. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it important to tell the history of spirituals carefully and truthfully? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Faith in Hard Times$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Spirituals and the Roots of American Music$j$, $j${"questions": [{"q": "Spirituals were created mainly by:", "options": ["Enslaved African Americans", "Baroque court musicians", "Radio engineers", "Medieval monks"]}, {"q": "A style in which a leader sings and the group answers is called:", "options": ["Rondo", "Fugue", "Call and response", "Crescendo"]}, {"q": "The Fisk Jubilee Singers were formed at:", "options": ["Notre Dame in Paris", "A radio station", "A Roman monastery", "Fisk University in Nashville"]}, {"q": "Spirituals draw much of their text from:", "options": ["Opera libretti", "Advertisements", "The Bible", "Newspapers"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Spirituals and the Roots of American Music$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,2}'::int[], array[$j$Spirituals grew from the faith and creativity of the enslaved.$j$,$j$Call and response is common in spirituals.$j$,$j$They began in 1871.$j$,$j$Exodus, Daniel and Jericho were favorite stories.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Spirituals and the Roots of American Music$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Gospel Music$j$, $j${"questions": [{"q": "The father of gospel music is:", "options": ["Thomas A. Dorsey", "Guido of Arezzo", "Palestrina", "Johann Sebastian Bach"]}, {"q": "Mahalia Jackson was called:", "options": ["The King of Chant", "The Father of Hymns", "The Queen of Gospel", "The Maker of Organs"]}, {"q": "Gospel music often includes:", "options": ["Only silent reading", "Choir, call and response, and improvisation", "Only bowed strings", "No words"]}, {"q": "First Peter 4:10 teaches that gifts should be used as:", "options": ["Good stewards of God's grace", "Ways to gain fame", "Secrets", "Private property"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Gospel Music$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,0}'::int[], array[$j$Dorsey helped shape gospel in the 1930s.$j$,$j$She was known across the country.$j$,$j$Gospel is expressive and communal.$j$,$j$Gifts are to serve others.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Gospel Music$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Blues, Jazz, Folk and Country$j$, $j${"questions": [{"q": "Jazz grew out of which city in the early 1900s?", "options": ["New Orleans", "Seattle", "Denver", "Boston"]}, {"q": "Improvisation means:", "options": ["Making up music on the spot", "Playing very softly", "Reading every note exactly", "Singing in Latin"]}, {"q": "Blue notes are:", "options": ["Very loud notes", "Notes for the organ only", "Bent pitches that sound expressive", "Silent rests"]}, {"q": "Shape note singing helps people:", "options": ["Write operas", "Record music", "Play the tuba", "Sing hymns in parts without instruments"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Blues, Jazz, Folk and Country$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,0,2,3}'::int[], array[$j$New Orleans is the birthplace of jazz.$j$,$j$Jazz players improvise.$j$,$j$Blue notes are a mark of the blues.$j$,$j$Sacred Harp singing is sung in four parts.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Blues, Jazz, Folk and Country$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Popular Music and Wise Listening$j$, $j${"questions": [{"q": "Hip hop began in:", "options": ["The Bronx in New York City in the 1970s", "Paris in the 1700s", "Rome in the Middle Ages", "Nashville in the 1800s"]}, {"q": "Philippians 4:8 tells us to think on things that are:", "options": ["Popular and expensive", "True, honest, just, pure and lovely", "Loud and fast", "New and unusual"]}, {"q": "A wise listener asks:", "options": ["Is it the newest?", "Are the words true and does the song help my walk with the Lord?", "Is it the loudest?", "Does everyone like it?"]}, {"q": "Very loud sound can:", "options": ["Heal the ears", "Damage hearing for life", "Do nothing", "Improve hearing"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Popular Music and Wise Listening$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,1}'::int[], array[$j$Hip hop emerged in the Bronx in the 1970s.$j$,$j$The verse gives a list for wise thinking.$j$,$j$Wise listening tests the message.$j$,$j$Protect your hearing.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Popular Music and Wise Listening$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: American Music Traditions$j$, $j${"questions": [{"q": "Spirituals often use:", "options": ["Only silence", "Electronic synthesizers", "Fugues", "Call and response"]}, {"q": "The Fisk Jubilee Singers began in:", "options": ["1741", "1871", "1969", "1501"]}, {"q": "Precious Lord, Take My Hand was written by:", "options": ["Thomas A. Dorsey", "Brahms", "Handel", "Isaac Watts"]}, {"q": "Jazz and blues both draw on:", "options": ["Renaissance madrigals only", "Opera only", "Medieval chant only", "African American musical roots"]}, {"q": "Syncopation is:", "options": ["Playing every note loudly", "Singing in Latin", "Stressing weak beats", "A form of rest"]}, {"q": "Shape note singing is also called:", "options": ["Sacred Harp singing", "Opera", "Rock and roll", "Gregorian chant"]}, {"q": "Romans 12:2 says to be transformed by:", "options": ["Popularity", "Following every trend", "The renewing of your mind", "Silence"]}, {"q": "A good test of any song, in any style, is:", "options": ["Is it loud?", "Is it new?", "Are the words true and does it honor God?", "Is it popular?"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: American Music Traditions$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,0,3,2,0,2,2}'::int[], array[$j$Call and response is a key feature.$j$,$j$They toured to raise money for Fisk University.$j$,$j$Dorsey wrote it in 1932.$j$,$j$Spirituals, work songs and field hollers fed both.$j$,$j$Syncopation shifts the stress to weak beats.$j$,$j$It is a tradition of singing hymns in parts.$j$,$j$A renewed mind tests what it hears.$j$,$j$Test the message and the heart.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: American Music Traditions$j$ on conflict (item_id) do nothing;
